-- Vendor stock NorgannonDB lists and a second source shows on Forever (ForeverDB.net's seen vendors, EG Link, Icy Veins), that the world's vendors lack
-- 2026_11_12_230_world_everlake_norgannondb_vendor_stock.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): allthethings 007a0073a43f4babfb7e, eg-link 9fcae73cc74fea4f1c4f, forever-db 67bf2ef637063d1a3963, foreverdb-net 2026-11-10.93d059be, item-history 8672fdc896ead1073a49, live-hotfixes 70862-a1137766129c, norgannondb a2a5bcf1031019093a3a, questiedb c0ce0c97ee449295ff1a, wago 1.60.1.70862, wowhead 2026-11-10, wowhead-tooltips parts/2026-11-10T133
-- Written against the fork world acore_world_dryrun.elstep_.
-- GPL-3.0: made from NorgannonDB (GPL-3.0; QuestieDB and pfQuest stock) and ForeverDB.net (Data from ForeverDB.net, GPL-3.0). Game names belong to Blizzard Entertainment. Icy Veins' WoW Forever database (db.icy-veins.com/wow-forever) witnesses rows and gives chances and prices.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

-- npc_vendor: items the vendor's stock lacks (only while the vendor is a spawned vendor, not where it already sells the item at another price, and never again once added)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`entry` int unsigned NOT NULL, `slot` smallint NOT NULL, `item` int NOT NULL, `maxcount` int unsigned NOT NULL, `incrtime` int unsigned NOT NULL, `ExtendedCost` int unsigned NOT NULL, `type` tinyint unsigned NOT NULL, `PlayerConditionID` int unsigned NOT NULL, `IgnoreFiltering` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`entry`, `item`, `ExtendedCost`, `type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `npc_vendor` t WHERE t.`entry` = s.`entry` AND t.`item` = s.`item` AND t.`ExtendedCost` = s.`ExtendedCost` AND t.`type` = s.`type`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'npc_vendor' AND r.`k1` = s.`entry` AND r.`k2` = s.`item` AND r.`k3` = s.`ExtendedCost` AND r.`k4` = s.`type`) AND NOT EXISTS (SELECT 1 FROM `npc_vendor` o WHERE o.`entry` = s.`entry` AND o.`item` = s.`item` AND o.`type` = s.`type`) AND EXISTS (SELECT 1 FROM `creature_template` c WHERE c.`entry` = s.`entry` AND (c.`npcflag` & 128) <> 0) AND EXISTS (SELECT 1 FROM `creature` c WHERE c.`id` = s.`entry`);
DROP TEMPORARY TABLE `everlake_import_stage`;
